import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { pathToFileURL } from 'node:url';
const root = process.argv[2];
if (!root) throw new Error('Exact review checkout path required');
const { createOpenRouterImagesAdapter } = await import(pathToFileURL(root + '/src/preflight/index.mjs'));
const { accessPlan, fixtureScope } = await import(pathToFileURL(root + '/fixtures/preflight/access-ports.mjs'));
const at = Date.parse('2031-03-04T05:06:07.000Z');
const digest = text => 'sha256:' + createHash('sha256').update(text).digest('hex');
const target = structuredClone(accessPlan({ cellId: 'image_generation', provider: 'openrouter' })
  .cells.find(cell => cell.cell_id === 'image_generation').target);
const input = { run_id: 'review:run', cell_id: 'image_generation', target,
  configuration: structuredClone(target.configuration), scope: structuredClone(fixtureScope),
  grant_ref: 'review:grant', deadline_at: new Date(at + 120000).toISOString() };
const nativeFreeze = Object.freeze;
const token = 'synthetic-global-freeze-review-token';
const observed = { final_clock: false, credential_exposure_callbacks: 0, real_prepare_calls: 0, fetch_calls: 0 };
let armed = false, pending = false;
const adapter = createOpenRouterImagesAdapter({
  credentialPort: { evidence_mode: 'live', async resolveCredential(request) {
    return { decision: 'resolved', evidence_mode: 'live', token,
      expires_at: new Date(at + 600000).toISOString(),
      binding: { service: request.service, account_ref: request.account_ref, project_ref: request.project_ref,
        target_binding_sha256: digest(JSON.stringify(request.target_binding)), grant_ref: request.grant_ref },
      evidence: { ref: 'review:evidence', sha256: digest('evidence'), pinned_revision: 'review:source',
        independent_review: { ref: 'review:review', sha256: digest('review') } } };
  } },
  dispatchPort: { get prepare() {
    if (armed) pending = true;
    return () => { observed.real_prepare_calls++; };
  }, async dispatch() { throw new Error('Unexpected dispatch'); } },
  fetchImpl: async () => { observed.fetch_calls++; throw new Error('Unexpected fetch'); },
  now() {
    if (pending && !observed.final_clock) {
      observed.final_clock = true;
      Object.freeze = value => {
        if (value?.token === token || value?.credential?.token === token) {
          observed.credential_exposure_callbacks++;
          Object.freeze = nativeFreeze;
        }
        return nativeFreeze(value);
      };
    }
    return at;
  }
});
armed = true;
let outcome;
try { outcome = await adapter.prepare(input); }
finally { Object.freeze = nativeFreeze; }
process.stdout.write(JSON.stringify({ mode: 'offline-synthetic', ...observed, prepared: outcome?.prepared === true }) + '\n');
assert.equal(observed.final_clock, true);
assert.equal(observed.fetch_calls, 0);
assert.equal(observed.credential_exposure_callbacks, 0, 'A replaced global Object.freeze must not observe preparation credentials');
assert.equal(observed.real_prepare_calls, 1);
assert.equal(outcome.prepared, true);

